import{bQ as e,aL as a,u as i,G as o}from"./chunks/framework.CNL6o8_w.js";const m=JSON.parse('{"title":"网关接入认证流程","description":"","frontmatter":{},"headers":[],"relativePath":"lightsmart/gateway/auth-flow.md","filePath":"lightsmart/gateway/auth-flow.md"}'),s={name:"lightsmart/gateway/auth-flow.md"};function d(n,t,c,l,p,r){return a(),i("div",null,[...t[0]||(t[0]=[o(`<h1 id="网关接入认证流程" tabindex="-1">网关接入认证流程 <a class="header-anchor" href="#网关接入认证流程" aria-label="Permalink to &quot;网关接入认证流程&quot;">​</a></h1><h2 id="完整流程" tabindex="-1">完整流程 <a class="header-anchor" href="#完整流程" aria-label="Permalink to &quot;完整流程&quot;">​</a></h2><div class="mermaid-container"><pre class="mermaid-source" style="display:none;">sequenceDiagram
    participant GW as 网关
    participant hapi
    participant EMQX
    participant mapi

    GW-&gt;&gt;hapi: 1. POST /hotel/device/get_gateway_mqtt_info_sn
    hapi--&gt;&gt;GW: { mq_id, mq_pass, api_version, server_id }

    GW-&gt;&gt;EMQX: 2. MQTT Connect (username=mq_id, password=mq_pass)
    EMQX-&gt;&gt;mapi: 3. POST /mqtt/auth (HTTP Webhook)
    mapi-&gt;&gt;mapi: 4. 查 license_tb 校验 mq_pass + status=1
    mapi--&gt;&gt;EMQX: { result: &quot;allow&quot; }

    EMQX-&gt;&gt;mapi: 5. $SYS/.../connected (上线事件)
    mapi-&gt;&gt;mapi: 6. 更新 device_tb.status=1 + device_mqtt_connect_tb

    GW-&gt;&gt;EMQX: 7. 订阅 {topicL1}/{mq_id}/ble_in
    GW-&gt;&gt;EMQX: 8. 订阅 {topicL1}/{mq_id}/system
    GW-&gt;&gt;EMQX: 9. 订阅 {topicL1}/{mq_id}/at_in
    GW-&gt;&gt;EMQX: 10. 发布 {topicL1}/{mq_id}/ble_out
    GW-&gt;&gt;EMQX: 11. 发布 {topicL1}/{mq_id}/system_out</pre><div class="mermaid"></div></div><h2 id="步骤说明" tabindex="-1">步骤说明 <a class="header-anchor" href="#步骤说明" aria-label="Permalink to &quot;步骤说明&quot;">​</a></h2><h3 id="步骤-1-获取-mqtt-连接信息" tabindex="-1">步骤 1：获取 MQTT 连接信息 <a class="header-anchor" href="#步骤-1-获取-mqtt-连接信息" aria-label="Permalink to &quot;步骤 1：获取 MQTT 连接信息&quot;">​</a></h3><p>网关通过 HTTP 请求 hapi 获取 MQTT 凭证，详见 <a href="./mqtt-info.html">MQTT 连接信息</a>。</p><h3 id="步骤-2-4-mqtt-连接认证" tabindex="-1">步骤 2-4：MQTT 连接认证 <a class="header-anchor" href="#步骤-2-4-mqtt-连接认证" aria-label="Permalink to &quot;步骤 2-4：MQTT 连接认证&quot;">​</a></h3><p>网关使用 <code>mq_id</code> / <code>mq_pass</code> 连接 EMQX。EMQX 通过 HTTP Webhook 调用 mapi 认证，详见 <a href="./mqtt-auth.html">MQTT 认证</a>。</p><p><strong>认证逻辑</strong>：</p><ul><li>查 <code>license_tb</code> 表，校验 <code>mq_pass</code> 匹配且 <code>status=1</code></li><li><code>license_type=1</code>（设备）的凭证才允许网关连接</li><li>认证失败返回 <code>{ &quot;result&quot;: &quot;deny&quot; }</code>，EMQX 断开连接</li></ul><h3 id="步骤-5-6-上线事件处理" tabindex="-1">步骤 5-6：上线事件处理 <a class="header-anchor" href="#步骤-5-6-上线事件处理" aria-label="Permalink to &quot;步骤 5-6：上线事件处理&quot;">​</a></h3><p>mapi 订阅 EMQX <code>$SYS</code> 系统主题，处理设备上线事件，详见 <a href="./online-event.html">设备上下线事件</a>。</p><h3 id="步骤-7-11-订阅与发布" tabindex="-1">步骤 7-11：订阅与发布 <a class="header-anchor" href="#步骤-7-11-订阅与发布" aria-label="Permalink to &quot;步骤 7-11：订阅与发布&quot;">​</a></h3><p>网关连接成功后，订阅下行主题、发布上行主题：</p><table tabindex="0"><thead><tr><th>方向</th><th>主题</th><th>格式</th><th>说明</th></tr></thead><tbody><tr><td>订阅</td><td><code>{topicL1}/{mq_id}/ble_in</code></td><td>hex</td><td>接收 BLE Mesh 控制指令</td></tr><tr><td>订阅</td><td><code>{topicL1}/{mq_id}/system</code></td><td>JSON</td><td>接收系统级指令（重启、OTA 等）</td></tr><tr><td>订阅</td><td><code>{topicL1}/{mq_id}/at_in</code></td><td>AT 命令</td><td>接收串口指令</td></tr><tr><td>发布</td><td><code>{topicL1}/{mq_id}/ble_out</code></td><td>hex</td><td>上报 BLE Mesh 设备状态</td></tr><tr><td>发布</td><td><code>{topicL1}/{mq_id}/system_out</code></td><td>JSON</td><td>上报系统级状态</td></tr><tr><td>发布</td><td><code>{topicL1}/{mq_id}/at_out</code></td><td>字符串</td><td>上报 AT 命令响应</td></tr></tbody></table><blockquote><p><strong>topicL1 确定</strong>：<code>api_version &gt; 1</code> 时用 <code>mqtt{server_id}</code>（如 <code>mqtt1</code>），否则用 <code>module_code</code>（如 <code>6zcrzknc</code>）。详见 <a href="./mqtt-topics.html">MQTT 主题格式</a>。</p></blockquote><blockquote><p><strong>异步发布</strong>：<code>ble_out</code> 和 <code>at_out</code> 的 MQTT 发布通过网关内部事件队列异步执行，避免 BLE 数据接收或 UART 处理被 MQTT 发布阻塞。</p></blockquote><h2 id="mqtt-config-配置机制" tabindex="-1">mqtt_config 配置机制 <a class="header-anchor" href="#mqtt-config-配置机制" aria-label="Permalink to &quot;mqtt_config 配置机制&quot;">​</a></h2><p>hapi <code>module/login</code> 接口在网关配网时下发 MQTT 服务器地址：</p><ul><li><code>secret.onesite</code> 为真：从 <code>global_config_tb.mqtt_config</code>（<code>config_name=&#39;mqtt_config&#39;</code>）读取</li><li>否则：使用硬编码 <code>MQTT_SERVER_MAP</code>（<code>1/2/3</code> 均指向 <code>42.121.217.172</code>）</li></ul><blockquote><p>分支条件是 <strong><code>secret.onesite</code></strong>（而非「生产/测试环境」）。依据 <code>service-lightsmart-hapi/src/controller/module/module.js:232-268</code>。</p></blockquote><p><code>mqtt_config</code> 的 <code>config_content</code> 格式：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;port&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1883</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;server&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;192.168.3.164&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;protocol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mqtt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;keepalive&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;server_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="根地址-base-url-与初启引导" tabindex="-1">根地址（base_url）与初启引导 <a class="header-anchor" href="#根地址-base-url-与初启引导" aria-label="Permalink to &quot;根地址（base_url）与初启引导&quot;">​</a></h2><p>网关固件上电后先经引导服务取得主 API 根地址，再调 register / login / nodelist：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. POST http://tiny.beancomm.net/api/module/module/get_time    → { &quot;time&quot;: &lt;unix 秒&gt; }</span></span>
<span class="line"><span>2. POST http://tiny.beancomm.net/api/module/module/certificate → { &quot;base_url&quot;: &quot;http://hotel.chintiot.com/hapi/&quot; }</span></span>
<span class="line"><span>3. 后续 register / login / nodelist 均以 base_url 为前缀拼接</span></span></code></pre></div><ul><li><strong>生效顺序</strong>：以 <code>certificate</code> 下发的 <code>base_url</code> 为准（实测 <code>http://hotel.chintiot.com/hapi/</code>），即线上主 API 为 <code>hotel.chintiot.com</code>。</li><li>固件二进制内置默认 <code>http://hotel.beancomm.net/api/v5/</code> <strong>仅作初启兜底</strong>；该地址已下线（nginx 404），运行时会被 <code>base_url</code> 覆盖。</li><li>调用方法须为 <strong>POST</strong>（GET 会因 <code>express.text</code> 不解析 body 而导致签名校验失败）。</li></ul><blockquote><p><strong>修订（2026-09-26，A2 裁定）</strong>：明确「用 chintiot.com」——以 <code>certificate</code> 下发的 <code>base_url</code> 为准，<code>hotel.beancomm.net</code> 仅作初启兜底。依据 <code>device-lightsmart-BCW018X/evidence/add_gateway_20260926_003201/result.md</code>（A1 轮实测）与 <code>融合对照账本.md:76</code>。</p></blockquote>`,28)])])}const u=e(s,[["render",d]]);export{m as __pageData,u as default};
